css:
/* ═══════════════════════════ TOKENS ═══════════════════════════ */
:root {
    --bg: #08090b;
    --bg-1: #0b0c10;
    --bg-2: #0d0f13;
    --bg-3: #111319;
    --border: rgba(255, 255, 255, .08);
    --border-2: rgba(255, 255, 255, .13);
    --border-violet: rgba(155, 125, 255, .28);

    --violet: #7c5cff;
    --violet-bright: #9b7dff;
    --violet-dim: #5b3fd1;
    --pink: #ff5da2;
    --amber: #ffb454;

    --grad: linear-gradient(120deg, #9b7dff 0%, #c084fc 45%, #ff5da2 100%);
    --grad-soft: linear-gradient(120deg, rgba(155, 125, 255, .16) 0%, rgba(255, 93, 162, .10) 100%);
    --grad-btn: linear-gradient(135deg, #8a63ff 0%, #b45cff 60%, #ff5da2 100%);

    --tx: #f5f5f7;
    --tx-2: #b7b7c2;
    --tx-3: #82828e;
    --tx-4: #4c4c56;

    --success: #4ade80;
    --danger: #f87171;
    --warning: #fb923c;

    --r-2xl: 28px;
    --r-xl: 22px;
    --r-lg: 16px;
    --r-md: 12px;
    --r-sm: 8px;
    --r-pill: 999px;

    --ease: all .22s cubic-bezier(.4, 0, .2, 1);
    --ease-spring: all .5s cubic-bezier(.16, 1, .3, 1);

    --nav-h: 72px;
    --font-display: 'Clash Display', 'Plus Jakarta Sans', sans-serif;
    --font-body: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
    --font-mono: 'JetBrains Mono', ui-monospace, monospace;

    --shadow-card: 0 1px 0 rgba(255, 255, 255, .03) inset, 0 10px 30px -12px rgba(0, 0, 0, .6);
    --shadow-glow: 0 0 0 1px rgba(124, 92, 255, .22), 0 12px 40px -8px rgba(124, 92, 255, .28);

    --ink: #04010f;
    --plum: #9b45ff;
    --plum-bright: #bf76ff;
    --rose: #e8399a;
    --amber-orange: #ff6d2e;
    --grad-nav: linear-gradient(135deg, #bf76ff 0%, #e8399a 52%, #ff6d2e 100%);
    --grad-btn-nav: linear-gradient(135deg, #9b45ff 0%, #e8399a 100%);
    --nav-border: rgba(155, 69, 255, .16);
    --glass-bg: rgba(15, 6, 35, .45);
    --glass-border: rgba(191, 118, 255, .18);
    --glass-blur: saturate(180%) blur(24px);
}

@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation-duration: .001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: .001ms !important;
        scroll-behavior: auto !important;
    }
}

/* ═══════════════════════════ RESET ═══════════════════════════ */
*,
*::before,
*::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}
html {
    font-size: 16px;
    scroll-behavior: smooth;
    height: 100%;
}
body {
    font-family: var(--font-body);
    background: var(--bg);
    color: var(--tx);
    min-height: 100vh;
    padding-top: calc(var(--nav-h) + 20px);
    -webkit-font-smoothing: antialiased;
    overflow-x: hidden;
    font-size: 16px;
    line-height: 1.5;
}
img {
    max-width: 100%;
    display: block;
}
button,
input,
select,
textarea {
    font-family: inherit;
    color: inherit;
}
a {
    color: inherit;
    text-decoration: none;
}
::selection {
    background: rgba(155, 125, 255, .35);
    color: #fff;
}
::-webkit-scrollbar {
    width: 8px;
    height: 8px;
}
::-webkit-scrollbar-track {
    background: transparent;
}
::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, .12);
    border-radius: 4px;
}
:focus-visible {
    outline: 2px solid var(--violet-bright);
    outline-offset: 2px;
    border-radius: 4px;
}

/* ═══════════════════════════ BACKGROUND ═══════════════════════════ */
.bg-canvas {
    position: fixed;
    inset: 0;
    z-index: 0;
    pointer-events: none;
    overflow: hidden;
}
.bg-orb {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: .55;
    animation: orbFloat 26s ease-in-out infinite;
}
.bg-orb-1 {
    width: 620px;
    height: 620px;
    top: -220px;
    left: -160px;
    background: radial-gradient(circle, rgba(124, 92, 255, .16) 0%, transparent 70%);
}
.bg-orb-2 {
    width: 520px;
    height: 520px;
    top: 30%;
    right: -200px;
    background: radial-gradient(circle, rgba(255, 93, 162, .10) 0%, transparent 70%);
    animation-delay: -10s;
}
.bg-grid {
    position: absolute;
    inset: 0;
    background-image: linear-gradient(rgba(255, 255, 255, .025) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255, 255, 255, .025) 1px, transparent 1px);
    background-size: 64px 64px;
    mask-image: radial-gradient(ellipse 80% 50% at 50% 0%, #000 40%, transparent 100%);
}
@keyframes orbFloat {
    0%,
    100% {
        transform: translate(0, 0) scale(1);
    }
    50% {
        transform: translate(24px, 30px) scale(1.05);
    }
}

/* ═══════════════════════════ SKIP LINK ═══════════════════════════ */
.skip-link {
    position: absolute;
    top: -9999px;
    left: 50%;
    transform: translateX(-50%);
    padding: 12px 22px;
    background: var(--violet);
    color: #fff;
    border-radius: var(--r-md);
    font-weight: 700;
    z-index: 9999;
}
.skip-link:focus {
    top: 12px;
}

/* ═══════════════════════════ DYNAMIC ISLAND NAV ═══════════════════════════ */
.dynamic-island {
    position: fixed;
    top: 12px;
    left: 50%;
    transform: translateX(-50%);
    z-index: 1000;
    width: auto;
    min-width: 280px;
    max-width: 92vw;
    height: 56px;
    background: rgba(8, 3, 22, .82);
    backdrop-filter: saturate(180%) blur(24px);
    -webkit-backdrop-filter: saturate(180%) blur(24px);
    border-radius: var(--r-pill);
    border: 1px solid rgba(191, 118, 255, .12);
    box-shadow: 0 8px 32px rgba(0, 0, 0, .5);
    display: flex;
    align-items: center;
    padding: 0 6px;
    gap: 2px;
    user-select: none;
    transition: all .3s cubic-bezier(.34, 1.56, .64, 1);
}
.dynamic-island::before {
    content: '';
    position: absolute;
    inset: -1px;
    border-radius: var(--r-pill);
    padding: 1px;
    background: linear-gradient(135deg, rgba(191, 118, 255, .12), rgba(232, 57, 154, .06));
    -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    pointer-events: none;
}
.island-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    height: 100%;
    padding: 0 4px;
    position: relative;
    z-index: 1;
}

.island-brand {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-shrink: 0;
    text-decoration: none;
    padding: 0 6px 0 4px;
    border-radius: var(--r-sm);
    transition: var(--ease);
}
.island-brand:hover {
    background: rgba(155, 69, 255, .04);
}
.island-brand-logo {
    width: 32px;
    height: 32px;
    border-radius: var(--r-xs);
    background: linear-gradient(135deg, rgba(155, 69, 255, .2), rgba(232, 57, 154, .12));
    border: 1px solid rgba(155, 69, 255, .2);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    overflow: hidden;
}
.island-brand-logo img {
    width: 18px;
    height: 18px;
    object-fit: contain;
}
.island-brand-text {
    font-family: 'Clash Display', sans-serif;
    font-size: .92rem;
    font-weight: 700;
    background: var(--grad-nav);
    background-size: 200% 200%;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    animation: gradShift 6s ease infinite;
    white-space: nowrap;
}


.island-links {
    display: flex;
    align-items: center;
    gap: 1px;
    flex: 1;
    justify-content: center;
    padding: 0 4px;
}
.island-link {
    display: flex;
    align-items: center;
    gap: 3px;
    padding: 5px 12px;
    border-radius: var(--r-sm);
    color: var(--tx-3);
    font-size: .75rem;
    font-weight: 600;
    background: none;
    border: none;
    cursor: pointer;
    transition: var(--ease);
    font-family: inherit;
    text-decoration: none;
    white-space: nowrap;
    position: relative;
}
.island-link:hover {
    color: var(--tx-2);
    background: rgba(155, 69, 255, .06);
}
.island-link .chevron {
    font-size: .5rem;
    opacity: .5;
    transition: transform .22s ease;
    margin-left: 1px;
}
.island-link .link-badge {
    font-size: .45rem;
    font-weight: 800;
    text-transform: uppercase;
    padding: 1px 5px;
    border-radius: var(--r-pill);
    background: rgba(232, 57, 154, .12);
    border: 1px solid rgba(232, 57, 154, .18);
    color: var(--rose);
    margin-left: 1px;
}

.island-dropdown-wrap {
    position: relative;
}
.island-dropdown {
    position: absolute;
    top: calc(100% + 8px);
    left: 50%;
    transform: translateX(-50%) translateY(4px);
    min-width: 200px;
    background: rgba(8, 3, 22, .96);
    backdrop-filter: saturate(180%) blur(24px);
    -webkit-backdrop-filter: saturate(180%) blur(24px);
    border: 1px solid rgba(155, 69, 255, .12);
    border-radius: var(--r-lg);
    padding: 6px 4px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, .7);
    opacity: 0;
    pointer-events: none;
    transition: opacity .2s ease, transform .2s ease;
    z-index: 100;
}
.island-dropdown-wrap:hover .island-dropdown,
.island-dropdown-wrap.open .island-dropdown {
    opacity: 1;
    pointer-events: all;
    transform: translateX(-50%) translateY(0);
}
.island-dropdown a,
.island-dropdown .dd-item {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 6px 12px;
    border-radius: var(--r-sm);
    color: var(--tx-3);
    font-size: .73rem;
    font-weight: 500;
    text-decoration: none;
    transition: var(--ease);
    cursor: pointer;
    background: none;
    border: none;
    width: 100%;
    text-align: left;
    font-family: inherit;
}
.island-dropdown a:hover,
.island-dropdown .dd-item:hover {
    background: rgba(155, 69, 255, .06);
    color: var(--tx-2);
}
.island-dropdown .dd-icon {
    font-size: .9rem;
    flex-shrink: 0;
}
.island-dropdown .dd-label {
    flex: 1;
}
.island-dropdown .dd-badge {
    font-size: .45rem;
    font-weight: 700;
    text-transform: uppercase;
    padding: 1px 6px;
    border-radius: var(--r-pill);
    background: rgba(232, 57, 154, .10);
    border: 1px solid rgba(232, 57, 154, .16);
    color: var(--rose);
}
.island-dropdown .dd-divider {
    height: 1px;
    background: linear-gradient(90deg, transparent, rgba(155, 69, 255, .08), transparent);
    margin: 4px 8px;
}
.island-dropdown .dd-admin {
    display: none;
}
.island-dropdown .dd-admin.visible {
    display: flex;
}

.island-right {
    display: flex;
    align-items: center;
    gap: 4px;
    flex-shrink: 0;
    padding-right: 2px;
}
.island-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 4px;
    padding: 5px 14px;
    border-radius: var(--r-pill);
    border: none;
    cursor: pointer;
    font-family: inherit;
    font-size: .73rem;
    font-weight: 700;
    transition: var(--ease-spring);
    text-decoration: none;
    white-space: nowrap;
    position: relative;
    overflow: hidden;
}
.island-btn::before {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 50%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, .08), transparent);
    transition: left .5s ease;
    pointer-events: none;
}
.island-btn:hover::before {
    left: 140%;
}
.island-btn-primary {
    background: var(--grad-btn-nav);
    color: #fff;
    box-shadow: 0 2px 12px rgba(155, 69, 255, .25);
}
.island-btn-primary:hover {
    box-shadow: 0 4px 20px rgba(155, 69, 255, .35);
    transform: translateY(-1px);
}
.island-btn-secondary {
    background: rgba(155, 69, 255, .06);
    color: var(--plum-bright);
    border: 1px solid rgba(155, 69, 255, .12);
}
.island-btn-secondary:hover {
    background: rgba(155, 69, 255, .12);
    border-color: rgba(155, 69, 255, .22);
    transform: translateY(-1px);
}
.island-btn-ghost {
    background: transparent;
    color: var(--tx-3);
    border: 1px solid rgba(255, 255, 255, .04);
}
.island-btn-ghost:hover {
    background: rgba(255, 255, 255, .04);
    color: var(--tx-2);
}
.island-btn-sm {
    padding: 4px 10px;
    font-size: .68rem;
}

.island-profile {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 2px 10px 2px 4px;
    border-radius: var(--r-pill);
    background: rgba(155, 69, 255, .04);
    border: 1px solid rgba(155, 69, 255, .08);
    cursor: pointer;
    transition: var(--ease);
}
.island-profile:hover {
    background: rgba(155, 69, 255, .08);
}
.island-avatar {
    width: 26px;
    height: 26px;
    border-radius: 50%;
    background: var(--grad-btn-nav);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: .65rem;
    font-weight: 800;
    color: #fff;
    flex-shrink: 0;
    box-shadow: 0 0 8px rgba(155, 69, 255, .15);
}
.island-profile-email {
    font-size: .68rem;
    font-weight: 600;
    color: var(--tx-2);
    max-width: 80px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.island-profile .chevron {
    font-size: .45rem;
    color: var(--tx-4);
}

.island-hamburger {
    display: none;
    flex-direction: column;
    gap: 3px;
    padding: 6px 8px;
    background: none;
    border: none;
    cursor: pointer;
    color: var(--tx);
    border-radius: var(--r-sm);
    transition: var(--ease);
    flex-shrink: 0;
}
.island-hamburger:hover {
    background: rgba(155, 69, 255, .04);
}
.island-hamburger span {
    display: block;
    width: 18px;
    height: 1.5px;
    background: currentColor;
    border-radius: 1px;
    transition: transform .28s cubic-bezier(.4, 0, .2, 1), opacity .2s ease;
}
.island-hamburger.open span:nth-child(1) {
    transform: translateY(4.5px) rotate(45deg);
}
.island-hamburger.open span:nth-child(2) {
    opacity: 0;
    transform: scaleX(0);
}
.island-hamburger.open span:nth-child(3) {
    transform: translateY(-4.5px) rotate(-45deg);
}

.island-mobile-overlay {
    display: none;
    position: fixed;
    inset: 0;
    z-index: 999;
    background: rgba(4, 1, 15, .92);
    backdrop-filter: blur(32px) saturate(160%);
    -webkit-backdrop-filter: blur(32px) saturate(160%);
    padding: 80px 20px 32px;
    overflow-y: auto;
    flex-direction: column;
    gap: 2px;
    animation: overlayFade .3s ease both;
}
@keyframes overlayFade {
    from {
        opacity: 0;
        transform: scale(.97);
    }
    to {
        opacity: 1;
        transform: scale(1);
    }
}
.island-mobile-overlay.open {
    display: flex;
}
.island-mobile-overlay .mob-section {
    padding: 8px 0 2px 12px;
    font-size: .55rem;
    text-transform: uppercase;
    letter-spacing: .12em;
    color: var(--tx-4);
    font-weight: 800;
    margin-top: 4px;
}
.island-mobile-overlay .mob-link {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px 14px;
    border-radius: var(--r-md);
    color: var(--tx-3);
    font-size: .85rem;
    font-weight: 600;
    text-decoration: none;
    transition: var(--ease);
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    font-family: inherit;
    cursor: pointer;
}
.island-mobile-overlay .mob-link:hover {
    background: rgba(155, 69, 255, .05);
    color: var(--tx-2);
}
.island-mobile-overlay .mob-link .mob-icon {
    font-size: 1rem;
    flex-shrink: 0;
}
.island-mobile-overlay .mob-link .mob-badge {
    font-size: .45rem;
    font-weight: 700;
    text-transform: uppercase;
    padding: 1px 6px;
    border-radius: var(--r-pill);
    background: rgba(232, 57, 154, .10);
    border: 1px solid rgba(232, 57, 154, .16);
    color: var(--rose);
    margin-left: auto;
}
.island-mobile-overlay .mob-divider {
    height: 1px;
    background: linear-gradient(90deg, transparent, rgba(155, 69, 255, .08), transparent);
    margin: 4px 12px;
}
.island-mobile-overlay .mob-auth-row {
    padding: 12px 14px 4px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}
.island-mobile-overlay .mob-auth-row .mob-email {
    font-size: .78rem;
    color: var(--tx-2);
    font-weight: 600;
    padding: 0 4px 4px;
}

.island-overlay-close {
    position: fixed;
    top: 16px;
    right: 20px;
    z-index: 1001;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: rgba(155, 69, 255, .06);
    border: 1px solid rgba(155, 69, 255, .12);
    color: var(--tx-3);
    font-size: 1.2rem;
    cursor: pointer;
    display: none;
    align-items: center;
    justify-content: center;
    transition: var(--ease);
}
.island-overlay-close:hover {
    background: rgba(155, 69, 255, .12);
    color: var(--tx);
}
.island-overlay-close.visible {
    display: flex;
}

@keyframes gradShift {
    0%,
    100% {
        background-position: 0% 50%;
    }
    50% {
        background-position: 100% 50%;
    }
}

/* ═══════ RESPONSIVE NAV ═══════ */
@media (max-width:1024px) {
    .dynamic-island {
        min-width: 200px;
        height: 50px;
        top: 10px;
    }
    .island-brand-text {
        font-size: .8rem;
    }

    .island-link {
        font-size: .7rem;
        padding: 4px 8px;
    }
    .island-btn {
        font-size: .68rem;
        padding: 4px 10px;
    }
    .island-profile-email {
        max-width: 60px;
        font-size: .62rem;
    }
}
@media (max-width:820px) {
    .island-links {
        display: none;
    }
    .island-hamburger {
        display: flex;
    }
    .dynamic-island {
        min-width: 140px;
        height: 44px;
        top: 8px;
        padding: 0 4px;
    }
    .island-brand-text {
        font-size: .72rem;
    }
    .island-brand-logo {
        width: 26px;
        height: 26px;
    }
    .island-brand-logo img {
        width: 15px;
        height: 15px;
    }
    .island-right .island-btn-secondary {
        display: none;
    }
    .island-right .island-btn-primary {
        padding: 3px 10px;
        font-size: .62rem;
    }
    .island-profile-email {
        max-width: 50px;
        font-size: .58rem;
    }
    .island-avatar {
        width: 22px;
        height: 22px;
        font-size: .55rem;
    }
    .island-profile {
        padding: 1px 6px 1px 2px;
    }
    .island-overlay-close.visible {
        display: flex;
    }
    body {
        padding-top: 64px;
    }
}
@media (max-width:480px) {
    .dynamic-island {
        min-width: 100px;
        height: 40px;
        top: 6px;
        padding: 0 2px;
    }
    .island-brand-text {
        font-size: .65rem;
    }
    .island-brand-logo {
        width: 22px;
        height: 22px;
    }
    .island-brand-logo img {
        width: 13px;
        height: 13px;
    }
    .island-brand {
        gap: 4px;
        padding: 0 2px;
    }
    .island-right .island-btn-primary {
        padding: 2px 8px;
        font-size: .55rem;
    }
    .island-right .island-btn-ghost {
        display: none;
    }
    .island-hamburger span {
        width: 15px;
        height: 1.5px;
    }
    .island-hamburger {
        padding: 4px 6px;
        gap: 2.5px;
    }
    .island-profile-email {
        max-width: 36px;
        font-size: .52rem;
    }
    .island-avatar {
        width: 20px;
        height: 20px;
        font-size: .5rem;
    }
    body {
        padding-top: 56px;
    }
}

/* ═══════════════════════════ UTILITY ═══════════════════════════ */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    padding: 8px 18px;
    border-radius: var(--r-md);
    border: none;
    cursor: pointer;
    font-family: inherit;
    font-size: .8rem;
    font-weight: 700;
    transition: var(--ease-spring);
    text-decoration: none;
    white-space: nowrap;
    position: relative;
    overflow: hidden;
}
.btn::before {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 60%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, .1), transparent);
    transition: left .5s ease;
    pointer-events: none;
}
.btn:hover::before {
    left: 140%;
}
.btn-primary {
    background: var(--grad-btn);
    color: #fff;
    box-shadow: 0 4px 20px rgba(155, 69, 255, .35);
}
.btn-primary:hover {
    box-shadow: 0 8px 32px rgba(155, 69, 255, .5);
    transform: translateY(-1px);
}
.btn-secondary {
    background: rgba(155, 69, 255, .08);
    color: var(--violet-bright);
    border: 1px solid rgba(155, 69, 255, .18);
}
.btn-secondary:hover {
    background: rgba(155, 69, 255, .16);
    border-color: rgba(155, 69, 255, .35);
    transform: translateY(-1px);
}
.btn-ghost {
    background: transparent;
    color: var(--tx-3);
    border: 1px solid rgba(255, 255, 255, .06);
}
.btn-ghost:hover {
    background: rgba(255, 255, 255, .04);
    color: var(--tx-2);
    border-color: rgba(255, 255, 255, .12);
}
.btn-sm {
    padding: 6px 14px;
    font-size: .74rem;
}
.btn-full {
    width: 100%;
}
.btn:disabled {
    opacity: .5;
    cursor: not-allowed;
    transform: none !important;
    box-shadow: none !important;
}
.spinner {
    display: inline-block;
    width: 14px;
    height: 14px;
    border-radius: 50%;
    border: 2px solid rgba(255, 255, 255, .25);
    border-top-color: #fff;
    animation: spin .65s linear infinite;
    flex-shrink: 0;
}
@keyframes spin {
    to {
        transform: rotate(360deg);
    }
}

.main-wrap {
    max-width: 1240px;
    margin: 0 auto;
    padding: 0 28px 60px;
    position: relative;
    z-index: 1;
}

.section {
    padding: 64px 0;
}
.section-divider {
    height: 1px;
    background: linear-gradient(90deg, transparent, var(--border) 20%, var(--border) 80%, transparent);
    margin: 0;
}
.section-eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: .74rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .09em;
    color: var(--violet-bright);
    margin-bottom: 16px;
}
.section-title {
    font-family: var(--font-display);
    font-size: clamp(1.9rem, 3.4vw, 2.7rem);
    font-weight: 600;
    letter-spacing: -.02em;
    line-height: 1.14;
    color: var(--tx);
    margin-bottom: 14px;
}
.section-sub {
    font-size: 1.02rem;
    color: var(--tx-3);
    max-width: 560px;
    line-height: 1.65;
}
.grad {
    background: var(--grad);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
}

.reveal {
    opacity: 0;
    transform: translateY(18px);
    transition: opacity .7s cubic-bezier(.16, 1, .3, 1), transform .7s cubic-bezier(.16, 1, .3, 1);
}
.reveal.in {
    opacity: 1;
    transform: translateY(0);
}
.stagger-1.in {
    transition-delay: .05s;
}
.stagger-2.in {
    transition-delay: .13s;
}
.stagger-3.in {
    transition-delay: .21s;
}

/* ═══════════════════════════ HERO (reduced size) ═══════════════════════════ */
.hero {
    display: grid;
    grid-template-columns: 1.05fr .95fr;
    gap: 28px;
    align-items: center;
    padding: 16px 0 32px;
}
.hero-badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 5px 12px 5px 8px;
    border-radius: var(--r-pill);
    background: rgba(124, 92, 255, .08);
    border: 1px solid var(--border-violet);
    font-size: .68rem;
    font-weight: 700;
    letter-spacing: .04em;
    text-transform: uppercase;
    color: var(--violet-bright);
    margin-bottom: 14px;
}
.hero-badge .dot {
    width: 5px;
    height: 5px;
    border-radius: 50%;
    background: var(--success);
    box-shadow: 0 0 0 3px rgba(74, 222, 128, .18);
    animation: pulseDot 2s ease-in-out infinite;
}
@keyframes pulseDot {
    0%,
    100% {
        opacity: 1;
    }
    50% {
        opacity: .4;
    }
}

.hero h1 {
    font-family: var(--font-display);
    font-size: clamp(2rem, 3.8vw, 3.2rem);
    font-weight: 600;
    letter-spacing: -.03em;
    line-height: 1.06;
    color: var(--tx);
    margin-bottom: 14px;
}
.hero p.hero-lead {
    font-size: 1rem;
    color: var(--tx-3);
    line-height: 1.65;
    max-width: 500px;
    margin-bottom: 20px;
}
.hero-actions {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 14px;
    flex-wrap: wrap;
}
.hero-trust {
    font-size: .78rem;
    color: var(--tx-4);
    margin-bottom: 20px;
}
.hero-trust strong {
    color: var(--tx-3);
    font-weight: 600;
}

.hero-stats-mini {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}
.hero-stat-item {
    display: flex;
    align-items: baseline;
    gap: 5px;
    padding: 6px 12px;
    border-radius: var(--r-md);
    background: var(--bg-2);
    border: 1px solid var(--border);
    font-size: .72rem;
    color: var(--tx-3);
}
.hero-stat-item strong {
    font-family: var(--font-display);
    font-size: .9rem;
    color: var(--tx);
    font-weight: 600;
}

.hero-visual {
    position: relative;
}
.hero-mock {
    position: relative;
    background: linear-gradient(180deg, var(--bg-3) 0%, var(--bg-2) 100%);
    border: 1px solid var(--border-2);
    border-radius: var(--r-2xl);
    box-shadow: var(--shadow-card), var(--shadow-glow);
    padding: 16px 18px 18px;
    overflow: hidden;
}
.hero-mock::before {
    content: "";
    position: absolute;
    top: -60%;
    right: -30%;
    width: 60%;
    height: 140%;
    background: radial-gradient(circle, rgba(155, 125, 255, .14) 0%, transparent 70%);
    pointer-events: none;
}
.mock-topbar {
    display: flex;
    align-items: center;
    gap: 5px;
    margin-bottom: 12px;
}
.mock-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: var(--border-2);
}
.mock-topbar-label {
    margin-left: auto;
    font-size: .6rem;
    color: var(--tx-4);
    font-family: var(--font-mono);
}

.mock-textarea {
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: var(--r-lg);
    padding: 12px 14px;
    min-height: 64px;
    margin-bottom: 12px;
}
.mock-textarea-line {
    height: 7px;
    border-radius: 4px;
    background: rgba(255, 255, 255, .09);
    margin-bottom: 7px;
}
.mock-textarea-line:nth-child(1) {
    width: 92%;
}
.mock-textarea-line:nth-child(2) {
    width: 78%;
}
.mock-textarea-line:nth-child(3) {
    width: 54%;
    margin-bottom: 0;
}

.mock-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
    margin-bottom: 12px;
}
.mock-field {
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: var(--r-md);
    padding: 8px 10px;
}
.mock-field-label {
    font-size: .55rem;
    text-transform: uppercase;
    letter-spacing: .06em;
    color: var(--tx-4);
    margin-bottom: 3px;
}
.mock-field-val {
    font-size: .74rem;
    color: var(--tx-2);
    display: flex;
    align-items: center;
    gap: 5px;
}
.mock-field-val .swatch {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: var(--grad);
    flex-shrink: 0;
}

.mock-generate {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    background: var(--grad-btn);
    border-radius: var(--r-md);
    padding: 8px;
    font-size: .74rem;
    font-weight: 700;
    color: #fff;
    margin-bottom: 12px;
    box-shadow: 0 4px 16px -4px rgba(124, 92, 255, .5);
}

.mock-player {
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: var(--r-lg);
    padding: 10px 12px;
    display: flex;
    align-items: center;
    gap: 10px;
}
.mock-play-btn {
    width: 28px;
    height: 28px;
    border-radius: 50%;
    background: var(--grad);
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: .6rem;
    color: #fff;
}
.mock-waveform {
    flex: 1;
    display: flex;
    align-items: center;
    gap: 2px;
    height: 22px;
}
.mock-waveform span {
    flex: 1;
    background: linear-gradient(180deg, var(--violet-bright), var(--pink));
    border-radius: 2px;
    opacity: .8;
    animation: wavePulse 1.6s ease-in-out infinite;
}
@keyframes wavePulse {
    0%,
    100% {
        transform: scaleY(.35);
    }
    50% {
        transform: scaleY(1);
    }
}
.mock-time {
    font-size: .6rem;
    color: var(--tx-4);
    font-family: var(--font-mono);
    flex-shrink: 0;
}

.hero-float-card {
    position: absolute;
    background: var(--bg-2);
    border: 1px solid var(--border-2);
    border-radius: var(--r-md);
    padding: 7px 12px;
    box-shadow: var(--shadow-card);
    font-size: .68rem;
    display: flex;
    align-items: center;
    gap: 6px;
    animation: floatCard 5s ease-in-out infinite;
}
.hero-float-card.f1 {
    bottom: -12px;
    left: -14px;
    color: var(--tx-2);
}
.hero-float-card.f2 {
    top: 14px;
    right: -18px;
    color: var(--tx-2);
    animation-delay: -2.5s;
}
.hero-float-card .fc-icon {
    color: var(--success);
}
@keyframes floatCard {
    0%,
    100% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-6px);
    }
}

/* ═══════ HERO RESPONSIVE ═══════ */
@media (max-width:1024px) {
    .hero {
        gap: 24px;
        padding: 12px 0 28px;
    }
}
@media (max-width:820px) {
    .hero {
        grid-template-columns: 1fr;
        gap: 20px;
        padding: 8px 0 20px;
        text-align: center;
    }
    .hero-content {
        align-items: center;
    }
    .hero p.hero-lead {
        max-width: 100%;
    }
    .hero-actions {
        justify-content: center;
    }
    .hero-trust {
        justify-content: center;
    }
    .hero-stats-mini {
        justify-content: center;
    }
    .hero-visual {
        max-width: 460px;
        margin: 0 auto;
    }
    .hero-float-card.f1 {
        bottom: -10px;
        left: 4px;
    }
    .hero-float-card.f2 {
        top: 10px;
        right: 4px;
        display: none;
    }
}
@media (max-width:480px) {
    .hero h1 {
        font-size: 1.8rem;
    }
    .hero p.hero-lead {
        font-size: .9rem;
    }
    .hero-actions .btn {
        width: 100%;
        justify-content: center;
    }
    .hero-float-card.f1 {
        bottom: -8px;
        left: 0;
        font-size: .6rem;
        padding: 4px 10px;
    }
}

/* ═══════════════════════════ STUDIO ═══════════════════════════ */
.studio-section {
    padding: 20px 0 64px;
}
.studio-description {
    font-size: .95rem;
    color: var(--tx-3);
    line-height: 1.7;
    max-width: 780px;
    margin: 0 auto 32px;
    text-align: center;
}
.studio-description strong {
    color: var(--tx-2);
    font-weight: 600;
}

.studio-card {
    background: var(--bg-1);
    border: 1px solid var(--border);
    border-radius: var(--r-2xl);
    overflow: hidden;
    box-shadow: var(--shadow-card);
}
.studio-head {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 22px 28px;
    border-bottom: 1px solid var(--border);
}
.studio-head-icon {
    width: 40px;
    height: 40px;
    border-radius: var(--r-md);
    background: var(--grad-soft);
    border: 1px solid var(--border-violet);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.1rem;
    flex-shrink: 0;
}
.studio-head h2 {
    font-family: var(--font-display);
    font-size: 1.2rem;
    font-weight: 600;
    letter-spacing: -.015em;
    color: var(--tx);
}
.studio-subtitle {
    font-size: .8rem;
    color: var(--tx-3);
    margin-top: 2px;
}

.tab-rail {
    display: flex;
    gap: 4px;
    padding: 12px 28px 0;
    overflow-x: auto;
}
.tab-btn {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 8px 14px;
    border-radius: var(--r-md) var(--r-md) 0 0;
    background: none;
    border: none;
    border-bottom: 2px solid transparent;
    color: var(--tx-3);
    font-size: .82rem;
    font-weight: 600;
    cursor: pointer;
    transition: var(--ease);
    white-space: nowrap;
}
.tab-btn:hover {
    color: var(--tx-2);
}
.tab-btn.active {
    color: var(--tx);
    border-bottom-color: var(--violet-bright);
}
.tab-icon {
    font-size: .9rem;
}
.tab-rail-underline {
    height: 1px;
    background: var(--border);
}

.studio-body {
    padding: 24px 28px 28px;
}
.tab-panel {
    display: none;
}
.tab-panel.active {
    display: block;
    animation: panelIn .35s cubic-bezier(.16, 1, .3, 1);
}
@keyframes panelIn {
    from {
        opacity: 0;
        transform: translateY(6px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.info-pill {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    padding: 12px 16px;
    border-radius: var(--r-md);
    background: rgba(124, 92, 255, .05);
    border: 1px solid rgba(124, 92, 255, .16);
    font-size: .82rem;
    color: var(--tx-2);
    line-height: 1.55;
    margin-bottom: 20px;
}
.info-pill-icon {
    flex-shrink: 0;
}

.loading-ring {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: .88rem;
    color: var(--tx-3);
    padding: 30px 0;
    justify-content: center;
}
.ring {
    width: 16px;
    height: 16px;
    border: 2px solid var(--border-2);
    border-top-color: var(--violet-bright);
    border-radius: 50%;
    animation: spin .8s linear infinite;
}

.field {
    margin-bottom: 16px;
}
.field label,
.field-label {
    display: block;
    font-size: .76rem;
    font-weight: 600;
    color: var(--tx-2);
    margin-bottom: 6px;
}
.field-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
}

.select-wrap {
    position: relative;
}
.select-wrap select {
    width: 100%;
    appearance: none;
    background: var(--bg);
    border: 1px solid var(--border-2);
    border-radius: var(--r-md);
    padding: 10px 38px 10px 14px;
    font-size: .86rem;
    color: var(--tx);
    cursor: pointer;
    transition: var(--ease);
    background-image: linear-gradient(45deg, transparent 50%, var(--tx-3) 50%), linear-gradient(135deg, var(--tx-3) 50%, transparent 50%);
    background-position: calc(100% - 18px) center, calc(100% - 13px) center;
    background-size: 5px 5px, 5px 5px;
    background-repeat: no-repeat;
}
.select-wrap select:focus {
    border-color: var(--violet-bright);
    box-shadow: 0 0 0 3px rgba(124, 92, 255, .15);
}
.select-wrap select:hover {
    border-color: var(--border-2);
    background-color: rgba(255, 255, 255, .02);
}

textarea,
input[type="text"],
input[type="email"],
input[type="password"] {
    width: 100%;
    background: var(--bg);
    border: 1px solid var(--border-2);
    border-radius: var(--r-md);
    padding: 11px 14px;
    font-size: .87rem;
    color: var(--tx);
    resize: vertical;
    transition: var(--ease);
}
textarea::placeholder,
input::placeholder {
    color: var(--tx-4);
}
textarea:focus,
input:focus {
    border-color: var(--violet-bright);
    box-shadow: 0 0 0 3px rgba(124, 92, 255, .15);
}

.char-caption {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: .72rem;
    color: var(--tx-4);
    margin-top: 6px;
}

.voice-card {
    margin: 4px 0 16px;
    padding: 14px;
    border-radius: var(--r-lg);
    background: var(--grad-soft);
    border: 1px solid var(--border-violet);
}
.vc-label {
    font-size: .66rem;
    text-transform: uppercase;
    letter-spacing: .06em;
    color: var(--violet-bright);
    font-weight: 700;
    margin-bottom: 4px;
}
.vc-name {
    font-family: var(--font-display);
    font-size: 1.1rem;
    font-weight: 600;
    color: var(--tx);
    margin-bottom: 3px;
    letter-spacing: -.01em;
}
.vc-desc {
    font-size: .8rem;
    color: var(--tx-3);
    margin-bottom: 10px;
}
.vc-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 5px;
}
.vc-tag {
    font-size: .7rem;
    font-weight: 600;
    padding: 3px 10px;
    border-radius: var(--r-pill);
    background: rgba(255, 255, 255, .06);
    border: 1px solid var(--border-2);
    color: var(--tx-2);
}
.vc-tag.neural {
    background: rgba(124, 92, 255, .14);
    border-color: rgba(124, 92, 255, .3);
    color: var(--violet-bright);
}
.vc-tag.studio {
    background: rgba(255, 93, 162, .12);
    border-color: rgba(255, 93, 162, .28);
    color: var(--pink);
}

.sliders-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-bottom: 16px;
}
.slider-group {}
.slider-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 6px;
}
.slider-label {
    font-size: .78rem;
    color: var(--tx-2);
    font-weight: 600;
}
.slider-val {
    font-size: .76rem;
    color: var(--violet-bright);
    font-family: var(--font-mono);
    font-weight: 600;
}
input[type="range"] {
    width: 100%;
    height: 4px;
    border-radius: 2px;
    background: var(--border-2);
    appearance: none;
    cursor: pointer;
}
input[type="range"]::-webkit-slider-thumb {
    appearance: none;
    width: 15px;
    height: 15px;
    border-radius: 50%;
    background: var(--tx);
    border: 3px solid var(--violet-bright);
    cursor: pointer;
    transition: var(--ease);
}
input[type="range"]::-webkit-slider-thumb:hover {
    transform: scale(1.12);
}
input[type="range"]::-moz-range-thumb {
    width: 15px;
    height: 15px;
    border-radius: 50%;
    background: var(--tx);
    border: 3px solid var(--violet-bright);
    cursor: pointer;
}

.cpu-toggle {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 16px;
    border-radius: var(--r-md);
    background: var(--bg);
    border: 1px solid var(--border);
    cursor: pointer;
    margin-bottom: 6px;
}
.toggle-switch {
    position: relative;
    width: 38px;
    height: 20px;
    flex-shrink: 0;
}
.toggle-switch input {
    opacity: 0;
    width: 100%;
    height: 100%;
    position: absolute;
    cursor: pointer;
    margin: 0;
}
.toggle-track {
    position: absolute;
    inset: 0;
    background: var(--border-2);
    border-radius: var(--r-pill);
    transition: var(--ease);
}
.toggle-track::after {
    content: "";
    position: absolute;
    top: 2px;
    left: 2px;
    width: 16px;
    height: 16px;
    background: var(--tx);
    border-radius: 50%;
    transition: var(--ease);
}
.toggle-switch input:checked+.toggle-track {
    background: var(--grad);
}
.toggle-switch input:checked+.toggle-track::after {
    transform: translateX(18px);
    background: #fff;
}
.toggle-info {
    flex: 1;
}
.toggle-label {
    font-size: .82rem;
    font-weight: 600;
    color: var(--tx);
}
.toggle-desc {
    font-size: .72rem;
    color: var(--tx-4);
    margin-top: 2px;
}

.progress-wrap {
    margin: 14px 0;
}
.progress-top {
    display: flex;
    justify-content: space-between;
    font-size: .74rem;
    color: var(--tx-3);
    margin-bottom: 6px;
}
.progress-track {
    height: 4px;
    border-radius: 3px;
    background: var(--border-2);
    overflow: hidden;
}
.progress-fill {
    height: 100%;
    background: var(--grad);
    border-radius: 3px;
    transition: width .5s cubic-bezier(.4, 0, .2, 1);
    width: 0%;
}

.audio-card {
    margin-top: 18px;
    padding: 18px;
    border-radius: var(--r-lg);
    background: var(--bg);
    border: 1px solid var(--border-violet);
}
.audio-eyebrow {
    display: flex;
    align-items: center;
    gap: 7px;
    font-size: .72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .05em;
    color: var(--success);
    margin-bottom: 8px;
}
.audio-eyebrow .dot {
    width: 5px;
    height: 5px;
    border-radius: 50%;
    background: var(--success);
}
.audio-title {
    font-family: var(--font-display);
    font-size: 1rem;
    font-weight: 600;
    color: var(--tx);
    margin-bottom: 2px;
}
.audio-meta {
    font-size: .76rem;
    color: var(--tx-3);
    margin-bottom: 12px;
}
audio {
    width: 100%;
    height: 38px;
    margin-bottom: 12px;
    border-radius: var(--r-sm);
}
.audio-actions {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
}

.blend-pill-row {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    flex-wrap: wrap;
    padding: 14px;
    border-radius: var(--r-md);
    background: var(--bg);
    border: 1px solid var(--border);
    margin-bottom: 16px;
    font-size: .84rem;
}
.blend-v-a {
    color: var(--violet-bright);
    font-weight: 700;
}
.blend-v-b {
    color: var(--pink);
    font-weight: 700;
}
.blend-vs {
    color: var(--tx-4);
}
.blend-pct {
    margin-left: auto;
    font-family: var(--font-mono);
    font-size: .74rem;
    color: var(--tx-3);
}

.glass-sep {
    height: 1px;
    background: var(--border);
    margin: 14px 0;
}
.pod-voice-pair {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
}
.pod-meta-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
    margin: 4px 0 16px;
}
.pod-meta-card {
    padding: 10px 12px;
    border-radius: var(--r-md);
    background: var(--bg);
    border: 1px solid var(--border);
}
.pod-meta-label {
    font-size: .64rem;
    text-transform: uppercase;
    letter-spacing: .06em;
    color: var(--tx-4);
    margin-bottom: 3px;
}
.pod-meta-val {
    font-size: .8rem;
    color: var(--tx-2);
    font-weight: 600;
}
.pod-preview {
    display: flex;
    flex-direction: column;
    gap: 6px;
    max-height: 240px;
    overflow-y: auto;
    padding-right: 4px;
}
.pod-row {
    display: flex;
    gap: 10px;
    padding: 8px;
    border-radius: var(--r-sm);
    background: var(--bg);
}
.pod-badge {
    width: 20px;
    height: 20px;
    border-radius: 5px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: .65rem;
    font-weight: 800;
    flex-shrink: 0;
}
.pod-badge.a {
    background: rgba(124, 92, 255, .16);
    color: var(--violet-bright);
}
.pod-badge.b {
    background: rgba(255, 93, 162, .14);
    color: var(--pink);
}
.pod-voice-name {
    font-size: .72rem;
    font-weight: 700;
    color: var(--tx-2);
    margin-bottom: 1px;
}
.pod-text {
    font-size: .78rem;
    color: var(--tx-3);
    line-height: 1.5;
}

.dropzone {
    position: relative;
    border: 1.5px dashed var(--border-2);
    border-radius: var(--r-lg);
    padding: 28px 18px;
    text-align: center;
    cursor: pointer;
    transition: var(--ease);
    margin-bottom: 16px;
}
.dropzone:hover,
.dropzone.drag-over {
    border-color: var(--violet-bright);
    background: rgba(124, 92, 255, .04);
}
.dropzone.has-file {
    border-color: var(--success);
    border-style: solid;
    background: rgba(74, 222, 128, .04);
}
.dropzone input[type="file"] {
    position: absolute;
    inset: 0;
    opacity: 0;
    cursor: pointer;
}
.dropzone-icon {
    font-size: 1.5rem;
    margin-bottom: 8px;
}
.dropzone-title {
    font-size: .86rem;
    font-weight: 600;
    color: var(--tx-2);
    margin-bottom: 3px;
}
.dropzone-sub {
    font-size: .74rem;
    color: var(--tx-4);
}

/* ═══════════════════════════ FEATURES ═══════════════════════════ */
.features-editorial {
    display: flex;
    flex-direction: column;
    gap: 16px;
}
.feature-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
}
.feature-block {
    background: var(--bg-1);
    border: 1px solid var(--border);
    border-radius: var(--r-xl);
    padding: 26px;
    position: relative;
    overflow: hidden;
    transition: var(--ease);
}
.feature-block:hover {
    border-color: var(--border-violet);
    transform: translateY(-2px);
}
.feature-block.wide {
    grid-column: 1 / -1;
    display: grid;
    grid-template-columns: 1fr 1.1fr;
    gap: 28px;
    align-items: center;
    padding: 30px;
}
.feature-icon {
    width: 38px;
    height: 38px;
    border-radius: var(--r-md);
    background: var(--grad-soft);
    border: 1px solid var(--border-violet);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1rem;
    margin-bottom: 14px;
}
.feature-title {
    font-family: var(--font-display);
    font-size: 1.05rem;
    font-weight: 600;
    letter-spacing: -.01em;
    color: var(--tx);
    margin-bottom: 6px;
}
.feature-desc {
    font-size: .85rem;
    color: var(--tx-3);
    line-height: 1.6;
}
.feature-visual {
    border-radius: var(--r-lg);
    background: var(--bg);
    border: 1px solid var(--border);
    padding: 16px;
    min-height: 120px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 8px;
}
.fv-bar {
    height: 6px;
    border-radius: 4px;
    background: rgba(255, 255, 255, .07);
}
.fv-bar.grad {
    background: var(--grad);
    opacity: .7;
}
.fv-chip-row {
    display: flex;
    gap: 6px;
    flex-wrap: wrap;
}
.fv-chip {
    font-size: .7rem;
    padding: 4px 10px;
    border-radius: var(--r-pill);
    background: rgba(255, 255, 255, .05);
    border: 1px solid var(--border-2);
    color: var(--tx-2);
}
.fv-mini-wave {
    display: flex;
    align-items: center;
    gap: 2px;
    height: 26px;
}
.fv-mini-wave span {
    flex: 1;
    background: var(--violet-bright);
    opacity: .55;
    border-radius: 2px;
}

.small-feature-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
}

/* ═══════════════════════════ TRUST STRIP ═══════════════════════════ */
.trust-strip {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1px;
    background: var(--border);
    border: 1px solid var(--border);
    border-radius: var(--r-lg);
    overflow: hidden;
    margin-top: 40px;
}
.trust-cell {
    background: var(--bg-1);
    padding: 20px 16px;
    text-align: center;
}
.trust-num {
    font-family: var(--font-display);
    font-size: 1.5rem;
    font-weight: 600;
    color: var(--tx);
    letter-spacing: -.01em;
}
.trust-label {
    font-size: .74rem;
    color: var(--tx-3);
    margin-top: 3px;
}

/* ═══════════════════════════ PRICING ═══════════════════════════ */
.pricing-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px;
    max-width: 760px;
}
.pricing-card {
    position: relative;
    background: var(--bg-1);
    border: 1px solid var(--border);
    border-radius: var(--r-xl);
    padding: 30px;
    transition: var(--ease);
}
.pricing-card:hover {
    border-color: var(--border-2);
    transform: translateY(-2px);
}
.pricing-card.featured {
    border-color: var(--border-violet);
    background: linear-gradient(180deg, rgba(124, 92, 255, .05), var(--bg-1) 55%);
    box-shadow: var(--shadow-glow);
}
.pricing-badge {
    position: absolute;
    top: -10px;
    left: 30px;
    font-size: .68rem;
    font-weight: 700;
    padding: 4px 12px;
    border-radius: var(--r-pill);
    background: var(--grad-btn);
    color: #fff;
}
.pricing-tier {
    font-size: .8rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .06em;
    color: var(--tx-3);
    margin-bottom: 12px;
}
.pricing-price {
    font-family: var(--font-display);
    font-size: 2.4rem;
    font-weight: 600;
    letter-spacing: -.02em;
    color: var(--tx);
}
.pricing-price.grad {
    background: var(--grad);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
}
.pricing-interval {
    font-size: .88rem;
    color: var(--tx-3);
    margin-left: 4px;
}
.pricing-summary {
    font-size: .84rem;
    color: var(--tx-3);
    margin: 10px 0 18px;
    line-height: 1.55;
}
.pricing-features {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 10px;
    margin-bottom: 22px;
}
.pricing-features li {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    font-size: .84rem;
    color: var(--tx-2);
}
.feat-check {
    color: var(--success);
    font-weight: 800;
    flex-shrink: 0;
}
.pricing-fineprint {
    font-size: .78rem;
    color: var(--tx-4);
    margin-top: 16px;
}

/* ═══════════════════════════ FAQ ═══════════════════════════ */
.faq-list {
    max-width: 760px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}
.faq-item {
    background: var(--bg-1);
    border: 1px solid var(--border);
    border-radius: var(--r-lg);
    overflow: hidden;
}
.faq-item summary {
    list-style: none;
    cursor: pointer;
    padding: 16px 20px;
    font-size: .92rem;
    font-weight: 600;
    color: var(--tx);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
}
.faq-item summary::-webkit-details-marker {
    display: none;
}
.faq-item summary::after {
    content: "+";
    font-size: 1.1rem;
    color: var(--tx-4);
    transition: transform .25s ease;
    flex-shrink: 0;
}
.faq-item[open] summary::after {
    transform: rotate(45deg);
    color: var(--violet-bright);
}
.faq-item[open] summary {
    border-bottom: 1px solid var(--border);
}
.faq-answer {
    padding: 4px 20px 18px;
    font-size: .85rem;
    color: var(--tx-3);
    line-height: 1.65;
}

/* ═══════════════════════════ TESTIMONIALS ═══════════════════════════ */
.testimonials-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
    margin-bottom: 40px;
}
.testimonial-card {
    background: var(--bg-1);
    border: 1px solid var(--border);
    border-radius: var(--r-lg);
    padding: 22px;
    transition: var(--ease);
    animation: fadeUp .6s cubic-bezier(.16, 1, .3, 1) both;
}
.testimonial-card:hover {
    border-color: var(--border-2);
}
@keyframes fadeUp {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}
.t-stars {
    color: var(--amber);
    font-size: .8rem;
    letter-spacing: 1px;
    margin-bottom: 10px;
}
.t-text {
    font-size: .85rem;
    color: var(--tx-2);
    line-height: 1.6;
    margin-bottom: 16px;
}
.t-author {
    display: flex;
    align-items: center;
    gap: 10px;
}
.t-avatar {
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: var(--grad-soft);
    border: 1px solid var(--border-violet);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: .65rem;
    font-weight: 800;
    color: var(--violet-bright);
    flex-shrink: 0;
}
.t-name {
    font-size: .8rem;
    font-weight: 700;
    color: var(--tx);
}
.t-role {
    font-size: .72rem;
    color: var(--tx-4);
}

.feedback-glass {
    max-width: 560px;
    margin: 0 auto;
    background: var(--bg-1);
    border: 1px solid var(--border);
    border-radius: var(--r-xl);
    padding: 28px;
    text-align: center;
}
.msg-ok {
    font-size: .82rem;
    color: var(--success);
    margin-bottom: 12px;
    padding: 10px;
    border-radius: var(--r-sm);
    background: rgba(74, 222, 128, .08);
}
.msg-err {
    font-size: .82rem;
    color: var(--danger);
    margin-bottom: 12px;
    padding: 10px;
    border-radius: var(--r-sm);
    background: rgba(248, 113, 113, .08);
}
.err {
    font-size: .78rem;
    color: var(--danger);
}

/* ═══════════════════════════ FOOTER ═══════════════════════════ */
.footer {
    padding: 56px 0 28px;
    border-top: 1px solid var(--border);
    margin-top: 32px;
}
.footer-inner {
    display: grid;
    grid-template-columns: 1.6fr 1fr 1fr;
    gap: 36px;
    padding-bottom: 40px;
}
.footer-brand-row {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 12px;
}
.footer-logo-wrap {
    width: 26px;
    height: 26px;
    border-radius: 8px;
    background: var(--grad);
    display: flex;
    align-items: center;
    justify-content: center;
}
.footer-logo-wrap img {
    width: 15px;
    height: 15px;
    filter: brightness(0) invert(1);
}
.footer-brand-name {
    font-family: var(--font-display);
    font-weight: 600;
    font-size: .95rem;
    color: var(--tx);
}
.footer-tagline {
    font-size: .83rem;
    color: var(--tx-3);
    max-width: 280px;
    line-height: 1.6;
    margin-bottom: 16px;
}
.footer-copy {
    font-size: .76rem;
    color: var(--tx-4);
    margin-bottom: 3px;
}
.footer-badges {
    display: flex;
    gap: 6px;
    flex-wrap: wrap;
    margin-top: 14px;
}
.footer-badge {
    font-size: .68rem;
    padding: 4px 10px;
    border-radius: var(--r-pill);
    border: 1px solid var(--border-2);
    color: var(--tx-3);
}
.badge-purple {
    border-color: rgba(124, 92, 255, .3);
    color: var(--violet-bright);
}
.badge-amber {
    border-color: rgba(255, 180, 84, .3);
    color: var(--amber);
}
.badge-green {
    border-color: rgba(74, 222, 128, .3);
    color: var(--success);
}
.footer-col-label {
    font-size: .72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .07em;
    color: var(--tx-4);
    margin-bottom: 14px;
}
.footer-links {
    display: flex;
    flex-direction: column;
    gap: 10px;
}
.footer-link {
    font-size: .83rem;
    color: var(--tx-3);
    transition: var(--ease);
}
.footer-link:hover {
    color: var(--tx);
}
.footer-bottom {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    padding-top: 22px;
    border-top: 1px solid var(--border);
    font-size: .76rem;
    color: var(--tx-4);
    flex-wrap: wrap;
}
.back-top-btn {
    background: none;
    border: 1px solid var(--border-2);
    border-radius: var(--r-md);
    padding: 6px 14px;
    font-size: .76rem;
    color: var(--tx-3);
    cursor: pointer;
    transition: var(--ease);
}
.back-top-btn:hover {
    color: var(--tx);
    border-color: var(--border-violet);
}

/* ═══════════════════════════ MODAL ═══════════════════════════ */
.modal-overlay {
    position: fixed;
    inset: 0;
    z-index: 2000;
    background: rgba(4, 4, 6, .7);
    backdrop-filter: blur(6px);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
    opacity: 1;
    transition: opacity .25s ease;
}
.modal-overlay.hidden {
    display: none;
}
.modal-box {
    position: relative;
    width: 100%;
    max-width: 420px;
    background: var(--bg-2);
    border: 1px solid var(--border-2);
    border-radius: var(--r-xl);
    padding: 30px;
    box-shadow: var(--shadow-card);
    animation: modalIn .3s cubic-bezier(.16, 1, .3, 1);
    max-height: 88vh;
    overflow-y: auto;
}
@keyframes modalIn {
    from {
        opacity: 0;
        transform: scale(.96) translateY(8px);
    }
    to {
        opacity: 1;
        transform: scale(1) translateY(0);
    }
}
.modal-close {
    position: absolute;
    top: 16px;
    right: 16px;
    width: 28px;
    height: 28px;
    border-radius: 50%;
    background: rgba(255, 255, 255, .05);
    border: 1px solid var(--border-2);
    color: var(--tx-3);
    cursor: pointer;
}
.modal-close:hover {
    color: var(--tx);
}
.modal-kicker {
    font-size: .72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .06em;
    color: var(--violet-bright);
    margin-bottom: 8px;
}
.modal-title {
    font-family: var(--font-display);
    font-size: 1.3rem;
    font-weight: 600;
    color: var(--tx);
    margin-bottom: 8px;
    letter-spacing: -.01em;
}
.modal-body-text {
    font-size: .85rem;
    color: var(--tx-3);
    line-height: 1.6;
    margin-bottom: 20px;
}
.auth-seg {
    display: flex;
    background: var(--bg);
    border: 1px solid var(--border-2);
    border-radius: var(--r-md);
    padding: 3px;
}
.auth-seg-btn {
    flex: 1;
    padding: 8px;
    border-radius: var(--r-sm);
    background: none;
    border: none;
    font-size: .82rem;
    font-weight: 600;
    color: var(--tx-3);
    cursor: pointer;
    transition: var(--ease);
}
.auth-seg-btn.active {
    background: var(--bg-2);
    color: var(--tx);
    box-shadow: var(--shadow-card);
}
.checkout-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
}

/* ═══════════════════════════ RESPONSIVE ═══════════════════════════ */
@media (max-width:1024px) {
    .section {
        padding: 48px 0;
    }
    .feature-row {
        grid-template-columns: 1fr;
    }
    .feature-block.wide {
        grid-template-columns: 1fr;
    }
    .small-feature-grid {
        grid-template-columns: repeat(2, 1fr);
    }
    .trust-strip {
        grid-template-columns: repeat(2, 1fr);
    }
    .footer-inner {
        grid-template-columns: 1fr 1fr;
        gap: 28px;
    }
    .footer-inner>div:first-child {
        grid-column: 1 / -1;
    }
}
@media (max-width:820px) {
    body {
        padding-top: calc(var(--nav-h) + 14px);
    }
    .main-wrap {
        padding: 0 18px 40px;
    }
    .section {
        padding: 36px 0;
    }
    .hero-actions {
        flex-direction: column;
        align-items: stretch;
    }
    .hero-actions .btn {
        width: 100%;
    }
    .field-row,
    .pod-voice-pair,
    .pod-meta-row,
    .mock-row {
        grid-template-columns: 1fr;
    }
    .sliders-row {
        grid-template-columns: 1fr;
    }
    .pricing-grid {
        grid-template-columns: 1fr;
        max-width: 420px;
    }
    .testimonials-grid {
        grid-template-columns: 1fr;
    }
    .small-feature-grid {
        grid-template-columns: 1fr;
    }
    .studio-head {
        padding: 16px 18px;
        flex-wrap: wrap;
    }
    .studio-head h2 {
        font-size: 1rem;
    }
    .tab-rail {
        padding: 10px 18px 0;
    }
    .tab-btn .tab-label {
        display: none;
    }
    .tab-btn {
        padding: 6px 10px;
        font-size: .75rem;
    }
    .studio-body {
        padding: 16px 18px 18px;
    }
    .studio-description {
        font-size: .85rem;
        padding: 0 4px;
    }
}
@media (max-width:480px) {
    .hero h1 {
        font-size: 1.6rem;
    }
    .hero p.hero-lead {
        font-size: .85rem;
    }
    .hero-stats-mini {
        gap: 4px;
    }
    .hero-stat-item {
        padding: 4px 8px;
        font-size: .65rem;
    }
    .hero-stat-item strong {
        font-size: .78rem;
    }
    .hero-mock {
        padding: 12px 14px 14px;
    }
    .mock-textarea {
        min-height: 48px;
        padding: 8px 10px;
    }
    .mock-textarea-line {
        height: 5px;
        margin-bottom: 5px;
    }
    .mock-row {
        gap: 6px;
    }
    .mock-field {
        padding: 6px 8px;
    }
    .mock-field-val {
        font-size: .68rem;
    }
    .mock-generate {
        font-size: .68rem;
        padding: 6px;
    }
    .mock-player {
        padding: 8px 10px;
    }
    .mock-play-btn {
        width: 24px;
        height: 24px;
        font-size: .5rem;
    }
    .mock-waveform {
        height: 18px;
    }
    .mock-time {
        font-size: .55rem;
    }
    .hero-float-card.f1 {
        bottom: -6px;
        left: 2px;
        font-size: .55rem;
        padding: 3px 8px;
    }
    .hero-float-card.f2 {
        display: none;
    }
    .footer-bottom {
        flex-direction: column;
        align-items: flex-start;
    }
    .pricing-card {
        padding: 20px 16px;
    }
    .modal-box {
        padding: 20px 16px;
    }
}

/* ═══════════════════════════ SOCIAL SHARING ═══════════════════════════ */
.social-share {
    display: flex;
    gap: 8px;
    margin-top: 16px;
    justify-content: center;
}
.social-share a {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: var(--r-pill);
    background: rgba(255, 255, 255, .04);
    border: 1px solid var(--border-2);
    color: var(--tx-3);
    transition: var(--ease);
    font-size: .85rem;
}
.social-share a:hover {
    background: rgba(255, 255, 255, .08);
    color: var(--tx);
    border-color: var(--border-violet);
    transform: translateY(-2px);
}

/* ═══════════════════════════ MISC ═══════════════════════════ */
.hidden {
    display: none !important;
}
.mt-12 {
    margin-top: 12px;
}
.banner {
    display: none;
    padding: 10px 16px;
    border-radius: var(--r-lg);
    background: rgba(124, 92, 255, .06);
    border: 1px solid rgba(124, 92, 255, .16);
    margin-bottom: 18px;
    align-items: center;
    gap: 10px;
    font-size: .8rem;
    color: var(--tx-3);
}
.banner-close {
    background: none;
    border: none;
    color: var(--tx-4);
    cursor: pointer;
    font-size: .85rem;
    padding: 0 4px;
}
.banner-close:hover {
    color: var(--tx-2);
}

scripts.content:
'use strict';

/* ─── CONFIG ─── */
const BASE_URL = "https://mohammadtalhaa-free-voice-labs-backend.hf.space";
const SESSION_KEY = "fvl_session";

const getSession = () => { try { const r = sessionStorage.getItem(SESSION_KEY); return r ? JSON.parse(r) : null; } catch {
        return null; } };
const setSession = d => { try { sessionStorage.setItem(SESSION_KEY, JSON.stringify(d)); } catch {} };
const clearSession = () => { try { sessionStorage.removeItem(SESSION_KEY); } catch {} };
const isLoggedIn = () => { const s = getSession(); return !!(s?.email && s?.token); };
const esc = s => String(s ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

async function apiFetch(path, opts = {}) {
    const s = getSession();
    const headers = { "Content-Type": "application/json", ...(s?.token ? { Authorization: `Bearer ${s.token}` } : {}),
        ...(opts.headers || {}) };
    const res = await fetch(`${BASE_URL}${path}`, { ...opts, headers: opts.formData ? (opts.headers || {}) :
            headers });
    if (!res.ok) { let m = `HTTP ${res.status}`; try { const e = await res.json();
            m = e.detail || e.message || m; } catch {} throw new Error(m); }
    if (opts.binary) return res;
    return res.json();
}

/* ─── STATE ─── */
let voicesData = { voices: {}, counts: {}, blends: {}, styles: {} };
let cmsData = {};
let activeTab = "standard";
let selectedVoice = "",
    selectedLib = "Live",
    selectedLang = "English (US)",
    selectedStyle = "Studio";
let customRate = 0,
    customPitch = 0,
    useMulticore = true;
let selectedBlend = "",
    blendRatio = 0.5,
    blendStyle = "Studio",
    blendRate = 0,
    blendPitch = 0;
let podVoiceA = "",
    podVoiceB = "";
let cloneFile = null,
    cloneFileName = "";
let audioBlob = null,
    audioURL = null,
    audioFormat = "wav";
let blendAudioBlob = null,
    blendAudioURL = null,
    blendAudioFormat = "wav";
let podAudioBlob = null,
    podAudioURL = null,
    podSegCount = 0;
let generating = false,
    genPodcast = false,
    progressInterval = null;
let checkoutPlan = null,
    authTab = "signin";
let isSignInMode = false;

const getVoices = () => voicesData.voices || {};
const getBlends = () => voicesData.blends || {};
const getStyles = () => voicesData.styles || {};

function getVoiceNames() {
    const vs = getVoices();
    return Object.entries(vs).filter(([, v]) => v.library === selectedLib && (!selectedLang || v.language ===
        selectedLang)).map(([name]) => name);
}

function getAllVoiceNames() { const vs = getVoices(); return Object.keys(vs); }

function getLanguages() {
    const vs = getVoices();
    const order = ["English (US)", "English (UK)", "Spanish (Spain)", "Spanish (US)", "French", "German", "Italian",
        "Japanese", "Mandarin Chinese", "Urdu", "Hindi", "Arabic", "Afrikaans", "Zulu", "Swahili",
        "Portuguese (Brazil)", "Portuguese (Portugal)", "Russian", "Turkish"
    ];
    return [...new Set(Object.values(vs).filter(v => v.library === selectedLib).map(v => v.language))].sort((a, b) =>
        (order.indexOf(a) + 1 || 999) - (order.indexOf(b) + 1 || 999));
}

function blendPct1() { return Math.round(blendRatio * 100); }

function blendPct2() { return 100 - blendPct1(); }

function podSentences(text) { return text.trim() ? text.trim().split(/(?<=[.!?])\s+/).filter(Boolean) : []; }

/* ─── PROGRESS ─── */
function startProgressSim(labels, prefix = "gen") {
    let i = 0,
        genProgress = 0,
        genLabel = labels[0] || "Initialising…";
    const steps = [10, 30, 55, 75, 90];
    const fillId = `${prefix}-progress-fill`,
        pctId = `${prefix}-progress-pct`,
        lblId = `${prefix}-progress-label`,
        wrapId = `${prefix}-progress-wrap`;
    const wrap = document.getElementById(wrapId);
    if (wrap) wrap.style.display = "";
    progressInterval = setInterval(() => {
        if (i < steps.length - 1) { i++;
            genProgress = steps[i];
            genLabel = labels[Math.min(i, labels.length - 1)]; }
        const fill = document.getElementById(fillId),
            pct = document.getElementById(pctId),
            lbl = document.getElementById(lblId);
        if (fill) fill.style.width = genProgress + "%";
        if (pct) pct.textContent = genProgress + "%";
        if (lbl) lbl.textContent = genLabel;
    }, 700);
}

function stopProgressSim(prefix = "gen") {
    clearInterval(progressInterval);
    progressInterval = null;
    const fill = document.getElementById(`${prefix}-progress-fill`),
        pct = document.getElementById(`${prefix}-progress-pct`),
        lbl = document.getElementById(`${prefix}-progress-label`),
        wrap = document.getElementById(`${prefix}-progress-wrap`);
    if (fill) fill.style.width = "100%";
    if (pct) pct.textContent = "100%";
    if (lbl) lbl.textContent = "Done!";
    setTimeout(() => { if (wrap) wrap.style.display = "none"; }, 800);
}

/* ─── AUDIO HELPERS ─── */
function clearAudio() { if (audioURL) URL.revokeObjectURL(audioURL);
    audioURL = null;
    audioBlob = null; const c = document.getElementById("audio-output-card"); if (c) c.style.display = "none"; }

function clearBlendAudio() { if (blendAudioURL) URL.revokeObjectURL(blendAudioURL);
    blendAudioURL = null;
    blendAudioBlob = null; const c = document.getElementById("blend-audio-output-card"); if (c) c.style.display =
        "none"; }

function clearPodcastAudio() { if (podAudioURL) URL.revokeObjectURL(podAudioURL);
    podAudioURL = null;
    podAudioBlob = null;
    podSegCount = 0; const c = document.getElementById("pod-output-card"); if (c) c.style.display = "none"; }

/* ─── VOICE CARD ─── */
function renderVoiceCard() {
    const vs = getVoices(),
        cfg = vs[selectedVoice],
        wrap = document.getElementById("voice-card-wrap");
    if (!wrap) return;
    if (!cfg) { wrap.innerHTML = ""; return; }
    const engineClass = cfg.engine === "neural" ? "neural" : "studio";
    const engineLabel = cfg.engine === "neural" ? "Neural" : "Studio";
    wrap.innerHTML =
        `<div class="voice-card"><div class="vc-label">${esc(cfg.collection_label || "")} · ${esc(cfg.language || "")}</div><div class="vc-name">${esc(selectedVoice)}</div><div class="vc-desc">${esc(cfg.tone || "")}</div><div class="vc-tags"><span class="vc-tag ${engineClass}">${engineLabel}</span><span class="vc-tag">${esc(cfg.gender || "")}</span><span class="vc-tag">${esc(cfg.accent || "")}</span>${cfg.age ? `<span class="vc-tag">${esc(cfg.age)}</span>` : ""}</div></div>`;
}

/* ─── POPULATE ─── */
function populateStandardForm() {
    const langEl = document.getElementById("voice-language");
    if (langEl) {
        const langs = getLanguages();
        const defaultLang = "English (US)";
        if (!selectedLang) selectedLang = defaultLang;
        langEl.innerHTML = `<option value="">All Languages</option>` + langs.map(l =>
            `<option value="${esc(l)}"${l === selectedLang ? " selected" : ""}>${esc(l)}</option>`).join("");
        if (langs.includes(defaultLang) && selectedLang === defaultLang) langEl.value = defaultLang;
    }
    const voiceEl = document.getElementById("voice-select");
    if (voiceEl) {
        const names = getVoiceNames();
        if (names.length) { voiceEl.innerHTML = names.map(n =>
                `<option value="${esc(n)}"${n === selectedVoice ? " selected" : ""}>${esc(n)}</option>`).join("");
            selectedVoice = voiceEl.value || names[0]; } else { voiceEl.innerHTML =
            `<option value="">No voices available</option>`;
            selectedVoice = ""; }
    }
    const styleEl = document.getElementById("style-select");
    if (styleEl) {
        const styles = getStyles();
        styleEl.innerHTML = Object.entries(styles).map(([k, v]) =>
            `<option value="${esc(k)}"${k === selectedStyle ? " selected" : ""}>${esc(v.label || k)}</option>`).join(
            "");
        selectedStyle = styleEl.value || "Studio";
    }
    renderVoiceCard();
    const ld = document.getElementById("std-loading"),
        fm = document.getElementById("std-form");
    if (ld) ld.style.display = "none";
    if (fm) fm.style.display = "";
}

function populateBlendForm() {
    const blends = getBlends(),
        keys = Object.keys(blends),
        blendEl = document.getElementById("blend-select");
    if (!blendEl) return;
    blendEl.innerHTML = `<option value="">— Select a blend —</option>` + keys.map(k =>
        `<option value="${esc(k)}">${esc(k)}</option>`).join("");
    const bStyleEl = document.getElementById("blend-style");
    if (bStyleEl) {
        const styles = getStyles();
        bStyleEl.innerHTML = Object.entries(styles).map(([k, v]) =>
            `<option value="${esc(k)}">${esc(v.label || k)}</option>`).join("");
    }
}

function populatePodcastForm() {
    const allVoices = getAllVoiceNames();
    const aEl = document.getElementById("pod-voice-a"),
        bEl = document.getElementById("pod-voice-b"),
        noVoiceEl = document.getElementById("podcast-no-voices");
    if (!allVoices.length) { if (noVoiceEl) noVoiceEl.style.display = ""; return; }
    if (noVoiceEl) noVoiceEl.style.display = "none";
    const opts = allVoices.map(n => `<option value="${esc(n)}">${esc(n)}</option>`).join("");
    if (aEl) { aEl.innerHTML = opts;
        podVoiceA = aEl.value || allVoices[0] || ""; }
    if (bEl) { bEl.innerHTML = opts; const second = allVoices.length > 1 ? allVoices[1] : allVoices[0];
        podVoiceB = bEl.value || second || "";
        if (allVoices.length === 1) { bEl.value = allVoices[0];
            podVoiceB = allVoices[0]; } }
    updatePodMeta();
    updatePodPreview();
}

function renderBlendCard() {
    const blends = getBlends(),
        cfg = blends[selectedBlend],
        card = document.getElementById("blend-card"),
        pctLbl = document.getElementById("blend-pct-label");
    if (!card) return;
    if (!cfg) { card.innerHTML = ""; return; }
    const p1 = blendPct1(),
        p2 = blendPct2();
    if (pctLbl) pctLbl.textContent = `${p1}% / ${p2}%`;
    card.innerHTML =
        `<span class="blend-v-a">${esc(cfg.voice_a || "Voice A")}</span><span class="blend-vs">×</span><span class="blend-v-b">${esc(cfg.voice_b || "Voice B")}</span><span class="blend-pct">${p1}% · ${p2}%</span>`;
}

function updatePodMeta() {
    const vs = getVoices(),
        cfgA = vs[podVoiceA],
        cfgB = vs[podVoiceB],
        metaRow = document.getElementById("pod-meta-row"),
        metaA = document.getElementById("pod-meta-a"),
        metaB = document.getElementById("pod-meta-b");
    if (!metaRow) return;
    if (podVoiceA || podVoiceB) { metaRow.style.display = "";
        if (metaA) metaA.textContent = podVoiceA ? `${podVoiceA}${cfgA ? ` · ${cfgA.gender || ""}` : ""}` : "—";
        if (metaB) metaB.textContent = podVoiceB ? `${podVoiceB}${cfgB ? ` · ${cfgB.gender || ""}` : ""}` : "—"; }
}

function updatePodPreview() {
    const text = (document.getElementById("pod-script")?.value || "").trim(),
        sents = podSentences(text),
        wrap = document.getElementById("pod-preview-wrap"),
        info = document.getElementById("pod-preview-info"),
        list = document.getElementById("pod-preview-list"),
        charInfo = document.getElementById("pod-char-info");
    if (charInfo) { const spans = charInfo.querySelectorAll("span"); if (spans[1]) spans[1].textContent =
            `${text.length.toLocaleString()} characters · Output: merged WAV`; }
    if (!sents.length) { if (wrap) wrap.style.display = "none"; return; }
    if (wrap) wrap.style.display = "";
    const cntA = sents.filter((_, i) => i % 2 === 0).length,
        cntB = sents.filter((_, i) => i % 2 !== 0).length;
    if (info) info.innerHTML =
        `Detected <strong style="color:var(--tx)">${sents.length}</strong> sentences → <strong style="color:var(--violet-bright)">${cntA} Voice A</strong> + <strong style="color:#60a5fa">${cntB} Voice B</strong>`;
    if (list) {
        const slice = sents.slice(0, 10);
        list.innerHTML = slice.map((s, i) =>
            `<div class="pod-row" role="listitem"><div class="pod-badge ${i % 2 === 0 ? 'a' : 'b'}">${i % 2 === 0 ? 'A' : 'B'}</div><div><div class="pod-voice-name">${esc(i % 2 === 0 ? podVoiceA : podVoiceB)}</div><div class="pod-text">${esc(s.slice(0, 130))}${s.length > 130 ? '…' : ''}</div></div></div>`
            ).join("") + (sents.length > 10 ?
            `<div class="char-caption" style="padding:8px 0 0;">+ ${sents.length - 10} more sentences</div>` :
            "");
    }
}

/* ─── TAB SWITCH ─── */
function switchTab(id) {
    activeTab = id;
    document.querySelectorAll(".tab-btn").forEach(b => { const a = b.dataset.tab === id;
        b.classList.toggle("active", a);
        b.setAttribute("aria-selected", a); });
    document.querySelectorAll(".tab-panel").forEach(p => { p.classList.toggle("active", p.id === `panel-${id}`); });
    clearAudio();
    clearBlendAudio();
    if (id === "podcast") { clearPodcastAudio();
        populatePodcastForm(); }
    if (id === "blend") populateBlendForm();
}

/* ─── GENERATE ─── */
async function handleGenerate() {
    const isBlend = activeTab === "blend";
    const scriptId = isBlend ? "blend-script" : "script-input";
    const text = document.getElementById(scriptId)?.value.trim() || "";
    if (!text || generating) return;
    generating = true;
    if (isBlend) clearBlendAudio();
    else clearAudio();
    const btnGen = document.getElementById("btn-generate"),
        btnBlnd = document.getElementById("btn-generate-blend");
    if (btnGen) { btnGen.disabled = true;
        btnGen.innerHTML = '<span class="spinner"></span> Generating…'; }
    if (btnBlnd) { btnBlnd.disabled = true;
        btnBlnd.innerHTML = '<span class="spinner"></span> Generating…'; }
    const prefix = isBlend ? "blend" : "gen";
    startProgressSim(["Initialising engine…", "Generating audio…", "Processing waveform…", "Applying style…",
        "Finalising output…"
    ], prefix);
    try {
        let body;
        if (isBlend) {
            body = { text, voice_name: "", style_name: blendStyle, custom_rate: blendRate,
                custom_pitch: blendPitch, use_blend: true, blend_name: selectedBlend,
                blend_ratio: blendRatio, use_multicore: document.getElementById("blend-multicore")
                    ?.checked ?? true, model: document.getElementById("voice-model")?.value || "" };
        } else {
            body = { text, voice_name: selectedVoice, style_name: selectedStyle, custom_rate: customRate,
                custom_pitch: customPitch, use_multicore: useMulticore, model: document.getElementById(
                    "voice-model")?.value || "" };
        }
        const res = await apiFetch("/api/tts/generate", { method: "POST", binary: true, body: JSON.stringify(
                body) });
        const fmt = res.headers.get("X-Audio-Format") || "wav";
        const blob = await res.blob();
        stopProgressSim(prefix);
        if (isBlend) {
            blendAudioBlob = blob;
            blendAudioFormat = fmt;
            blendAudioURL = URL.createObjectURL(blob);
            const e = document.getElementById("blend-audio-eyebrow"),
                t = document.getElementById("blend-audio-title"),
                m = document.getElementById("blend-audio-meta"),
                p = document.getElementById("blend-audio-player"),
                c = document.getElementById("blend-audio-output-card"),
                d = document.getElementById("blend-btn-download");
            if (e) e.textContent = `Blend Ready · ${fmt.toUpperCase()}`;
            if (t) t.textContent = `${selectedBlend} (${blendPct1()}% blend)`;
            if (m) m.textContent = `${blendStyle} · ${fmt.toUpperCase()} · Human-enhanced`;
            if (p) p.src = blendAudioURL;
            if (c) c.style.display = "";
            if (d) d.textContent = `Download ${fmt.toUpperCase()}`;
            if (isLoggedIn()) { const s = getSession();
                saveHistory(s.email, `${selectedBlend} blend`, blendStyle, text.length); }
        } else {
            audioBlob = blob;
            audioFormat = fmt;
            audioURL = URL.createObjectURL(blob);
            const e = document.getElementById("audio-output-eyebrow"),
                t = document.getElementById("audio-output-title"),
                m = document.getElementById("audio-output-meta"),
                p = document.getElementById("audio-player"),
                c = document.getElementById("audio-output-card"),
                d = document.getElementById("btn-download");
            if (e) e.textContent = `Audio Ready · ${fmt.toUpperCase()}`;
            if (t) t.textContent = selectedVoice;
            if (m) m.textContent = `${selectedStyle} · ${fmt.toUpperCase()} · Human-enhanced`;
            if (p) p.src = audioURL;
            if (c) c.style.display = "";
            if (d) d.textContent = `Download ${fmt.toUpperCase()}`;
            if (isLoggedIn()) { const s = getSession();
                saveHistory(s.email, selectedVoice, selectedStyle, text.length); }
        }
    } catch (e) { stopProgressSim(prefix);
        alert("Generation failed: " + e.message); } finally {
        generating = false;
        if (btnGen) { btnGen.disabled = false;
            btnGen.innerHTML = "Generate Voice"; }
        if (btnBlnd) { btnBlnd.disabled = false;
            btnBlnd.innerHTML = "Generate Blend"; }
    }
}

/* ─── PODCAST ─── */
async function handleGeneratePodcast() {
    const text = document.getElementById("pod-script")?.value.trim() || "";
    if (!text || genPodcast) return;
    if (podVoiceA === podVoiceB) { alert("Please select two DIFFERENT voices"); return; }
    const vs = getVoices(),
        cfgA = vs[podVoiceA],
        cfgB = vs[podVoiceB];
    if (!cfgA?.id || !cfgB?.id) { alert("Voice config not found"); return; }
    genPodcast = true;
    clearPodcastAudio();
    const btn = document.getElementById("btn-generate-podcast");
    if (btn) { btn.disabled = true;
        btn.innerHTML = '<span class="spinner"></span> Generating podcast…'; }
    startProgressSim(["Parsing sentences…", "Generating Voice A…", "Generating Voice B…", "Merging & mastering…",
        "Finalising…"
    ], "pod");
    try {
        const res = await apiFetch("/api/tts/podcast", { method: "POST", binary: true, body: JSON.stringify({
                script: text, voice_a_id: cfgA.id, voice_b_id: cfgB.id, use_multicore: true }) });
        const blob = await res.blob();
        const segCount = parseInt(res.headers.get("X-Segment-Count") || "0", 10);
        if (!blob || blob.size === 0) throw new Error("Empty audio response");
        stopProgressSim("pod");
        podAudioBlob = blob;
        podSegCount = segCount;
        podAudioURL = URL.createObjectURL(blob);
        const m = document.getElementById("pod-output-meta"),
            p = document.getElementById("pod-audio-player"),
            c = document.getElementById("pod-output-card");
        if (m) m.textContent = `${segCount} segments · ${Math.round(blob.size / 1024)} KB`;
        if (p) p.src = podAudioURL;
        if (c) c.style.display = "";
    } catch (e) { stopProgressSim("pod");
        alert("Podcast generation failed: " + e.message); } finally { genPodcast = false; if (btn) { btn.disabled =
                false;
            btn.innerHTML = "Generate Podcast"; } }
}

/* ─── CLONE ─── */
async function handleGenerateClone() {
    const text = document.getElementById("clone-text")?.value.trim() || "";
    if (!text || !cloneFile || generating) return;
    if (!document.getElementById("clone-consent")?.checked) { alert("Please confirm you have permission to clone this voice."); return; }
    generating = true;
    clearAudio();
    const btn = document.getElementById("btn-generate-clone");
    if (btn) { btn.disabled = true;
        btn.innerHTML = '<span class="spinner"></span> Cloning voice…'; }
    startProgressSim(["Loading model…", "Processing sample…", "Cloning voice…", "Rendering audio…",
        "Finalising…"
    ], "clone");
    try {
        const fd = new FormData();
        fd.append("text", text);
        fd.append("language", document.getElementById("clone-lang")?.value || "en");
        fd.append("sample", cloneFile);
        const s = getSession();
        const res = await fetch(`${BASE_URL}/api/tts/clone`, { method: "POST", headers: s?.token ?
                { Authorization: `Bearer ${s.token}` } : {}, body: fd });
        if (!res.ok) { const e = await res.json().catch(() => ({ detail: "Clone failed" }));
            throw new Error(e.detail || "Clone failed"); }
        const blob = await res.blob();
        stopProgressSim("clone");
        audioBlob = blob;
        audioFormat = "wav";
        audioURL = URL.createObjectURL(blob);
        const e = document.getElementById("audio-output-eyebrow"),
            t = document.getElementById("audio-output-title"),
            m = document.getElementById("audio-output-meta"),
            p = document.getElementById("audio-player"),
            c = document.getElementById("audio-output-card"),
            d = document.getElementById("btn-download");
        if (e) e.textContent = "Clone Ready · WAV";
        if (t) t.textContent = cloneFileName;
        if (m) m.textContent = "Voice Clone · WAV · Human-enhanced";
        if (p) p.src = audioURL;
        if (c) c.style.display = "";
        if (d) d.textContent = "Download WAV";
    } catch (e) { stopProgressSim("clone");
        alert("Clone failed: " + e.message); } finally { generating = false; if (btn) { btn.disabled = false;
            btn.innerHTML = "Generate Cloned Voice"; } }
}

