    document.getElementById("btn-clear-podcast")?.addEventListener("click", clearPodcastAudio);

    document.getElementById("clone-file-input")?.addEventListener("change", e => { const f = e.target.files?.[
        0
    ]; if (!f) return;
        cloneFile = f;
        cloneFileName = f.name; const dz = document.getElementById("clone-dropzone"),
            txt = document.getElementById("clone-dropzone-text"); if (dz) dz.classList.add("has-file"); if (
            txt) txt.innerHTML =
            `<div style="color:#4ade80;font-weight:700;font-size:.9rem;">${esc(f.name)}</div><div class="dropzone-sub">${(f.size / 1024).toFixed(1)} KB · ${esc(f.type || 'audio')}</div>`; });
    const dz = document.getElementById("clone-dropzone");
    dz?.addEventListener("dragover", e => { e.preventDefault();
        dz.classList.add("drag-over"); });
    dz?.addEventListener("dragleave", () => dz.classList.remove("drag-over"));
    dz?.addEventListener("drop", e => { e.preventDefault();
        dz.classList.remove("drag-over"); const f = e.dataTransfer?.files?.[0]; if (!f) return;
        cloneFile = f;
        cloneFileName = f.name;
        dz.classList.add("has-file"); const txt = document.getElementById("clone-dropzone-text"); if (txt)
            txt.innerHTML =
            `<div style="color:#4ade80;font-weight:700;font-size:.9rem;">${esc(f.name)}</div><div class="dropzone-sub">${(f.size / 1024).toFixed(1)} KB</div>`; });
    dz?.addEventListener("keydown", e => { if (e.key === "Enter" || e.key === " ") { e.preventDefault();
            document.getElementById("clone-file-input")?.click(); } });
    document.getElementById("btn-generate-clone")?.addEventListener("click", handleGenerateClone);
    document.getElementById("btn-feedback")?.addEventListener("click", handleFeedback);

    document.addEventListener("input", e => {
        if (e.target.id === "ck-card") { let v = e.target.value.replace(/\D/g, "").slice(0, 16);
            e.target.value = v.replace(/(.{4})/g, "$1 ").trim(); }
        if (e.target.id === "ck-expiry") { let v = e.target.value.replace(/\D/g, "").slice(0, 4); if (v
                .length >= 3) v = v.slice(0, 2) + "/" + v.slice(2);
            e.target.value = v; }
    });

    window.addEventListener("resize", () => { if (window.innerWidth > 820) closeMobileNav(); });
}

/* ─── CONSENT & ADS (AdSense loads only after explicit consent) ─── */
const CONSENT_KEY = "fvl_consent_v1";
const ADS_SRC = "https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-2940015635760134";
function loadAds() { if (document.getElementById("adsbygoogle-js")) return; const sc = document.createElement("script");
    sc.id = "adsbygoogle-js";
    sc.async = true;
    sc.crossOrigin = "anonymous";
    sc.src = ADS_SRC;
    document.head.appendChild(sc); }
function getConsent() { try { return JSON.parse(localStorage.getItem(CONSENT_KEY)); } catch { return null; } }
function setConsent(ads) { try { localStorage.setItem(CONSENT_KEY, JSON.stringify({ ads, v: 1, ts: new Date()
            .toISOString() })); } catch {} const b = document.getElementById("consent-bar"); if (b) b.style.display = "none"; if (ads) loadAds(); }

/* ─── BOOT ─── */
async function boot() {
    const yr = new Date().getFullYear();
    const f = document.getElementById("footer-year"); if (f) f.textContent =
        `© ${yr} Free Voice Labs. All rights reserved.`;

    renderNavAuth();
    renderMobileNav();
    setupReveal();
    setupEvents();
    const consent = getConsent();
    if (consent?.ads) loadAds();
    else if (!consent) { const b = document.getElementById("consent-bar"); if (b) b.style.display = ""; }

    try {
        cmsData = await apiFetch("/api/cms");
        if (cmsData.announcement) { const a = document.getElementById("announcement"),
                t = document.getElementById("announcement-text"); if (t) t.textContent = cmsData
                .announcement; if (a) a.style.display = "flex"; }
        if (cmsData.pricing_pro_price) { const e = document.getElementById("pro-price"); if (e) e.textContent =
                "$" + cmsData.pricing_pro_price; }
        if (cmsData.pricing_unlimited_price) { const e = document.getElementById("unlimited-price"); if (e) e
                .textContent = "$" + cmsData.pricing_unlimited_price; }
    } catch {}

    try {
        const data = await apiFetch("/api/voices");
        voicesData = data;
        const counts = data.counts || {};
        const sn = document.getElementById("stat-neural-hero"),
            ss = document.getElementById("stat-studio-hero"),
            sb = document.getElementById("stat-blends-hero");
        if (counts.live && sn) sn.textContent = counts.live + "+";
        if (counts.studio && ss) ss.textContent = counts.studio + "+";
        if (sb) { const bc = Object.keys(data.blends || {}).length;
            sb.textContent = bc; }
        populateStandardForm();
        populateBlendForm();
        populatePodcastForm();
    } catch (e) { const l = document.getElementById("std-loading"); if (l) l.innerHTML =
            `<span style="color:var(--danger);">Failed to load voices: ${esc(e.message)}</span>`; }

    try { const r = await apiFetch("/api/feedback/approved"); const list = (r.feedback || []).map(f => ({ text: f.comment }));
        renderTestimonials(list); } catch { renderTestimonials([]); }

    setTimeout(checkAndShowAdminLink, 500);
}

